/* Season picker and explicit legacy migration. Movies stay independent. */
const SeasonManager=(()=>{
 const M=SeasonModel,key='anishelf-series-archive-v1';let session=null,generation=0,busy=false;
 const en=()=>I18n.getLanguage()==='en-US',say=(zh,english)=>en()?english:zh;
 const legacy=a=>!M.isSeason(a)&&!M.isMerged(a)&&a.tmdbType!=='movie';
 const owned=(base,n)=>M.leaves(library).some(a=>M.isSeason(a)&&M.identity(a)===M.identity(base,n));
 function archive(){const records=JSON.parse(AppStorage.getItem(key)||'[]');if(!Array.isArray(records)||records.length>5000||records.some(r=>!r||typeof r.id!=='string'||!r.source||!Array.isArray(r.history)||!Array.isArray(r.seasonIds)))throw Error(say('原始系列档案格式错误，请先导出浏览器数据。','Invalid series archive; export browser data before continuing.'));DataSafety.validateCatalog(records.map(r=>r.source));return records}
 function withArchive(incoming,commit){if(incoming===undefined)return commit();if(!Array.isArray(incoming)||incoming.length>5000||incoming.some(r=>!r||typeof r.id!=='string'||!r.source||!Array.isArray(r.history)||!Array.isArray(r.seasonIds)))throw Error('Invalid series archive');DataSafety.validateCatalog(incoming.map(r=>r.source));const before=AppStorage.getItem(key),next=[...new Map([...archive(),...incoming].map(r=>[r.id,r])).values()];AppStorage.setItem(key,JSON.stringify(next));try{return commit()}catch(error){try{before===null?AppStorage.removeItem(key):AppStorage.setItem(key,before)}catch{}throw error}}
 function datesValid(value){return !value||WatchHistory.validDate(value)}
 function fields(row){const n=row.number;return '<div class="season-tracking-fields"><label>'+say('进度','Progress')+'<input type="number" min="0" max="'+row.episodes+'" id="seasonProgress'+n+'" value="'+row.progress+'"></label><label>'+say('状态','Status')+'<select id="seasonStatus'+n+'">'+Object.entries(statuses).map(([k,v])=>'<option value="'+k+'"'+(row.status===k?' selected':'')+'>'+esc(v)+'</option>').join('')+'</select></label><label>'+say('重看次数','Rewatch count')+'<input type="number" min="0" max="999" id="seasonRewatch'+n+'" value="'+row.rewatchCount+'"></label><label>'+say('开始观看','Watch started')+'<input type="date" id="seasonStart'+n+'"></label><label>'+say('完成观看','Watch finished')+'<input type="date" id="seasonFinish'+n+'"></label></div>'}
 function draw(){const s=session;if(!s)return;const migration=!!s.source;$('#seasonDialogTitle').textContent=s.base.seriesTitle||s.base.title;$('#seasonDialogHelp').textContent=migration?say('请确认累计进度按季度顺序分配。重看次数只是原记录的建议值，可逐季修正。备注只放到第一季（未选择第一季时保留在档案）；评分、观看日期和原始记录保存在系列档案中。','Review the sequential progress allocation. Rewatch counts are suggestions from the original; correct them per season. Notes go to Season 1 only (or remain archived if Season 1 is not selected). Original ratings, watch dates and records are archived.'):say('选择需要收藏的季度；特别篇默认不选。每季拥有独立进度、排番和重看记录。','Select seasons to collect. Specials are not selected by default. Each season has independent progress, scheduling and rewatches.');
  const suggestions=new Map((migration?M.suggestions(s.source,s.seasons):[]).map(r=>[r.number,r]));
  $('#seasonRows').inert=busy;$('#seasonConfirmRow').inert=busy;$('#seasonRows').innerHTML=s.seasons.map(season=>{const duplicate=owned(s.base,season.number),r={...season,...(suggestions.get(season.number)||{progress:0,status:'planned',rewatchCount:0})};return '<article class="season-choice"><label class="season-choice-heading"><input type="checkbox" data-season-choice="'+season.number+'"'+(duplicate?' disabled':'')+(migration&&season.number>0&&!duplicate?' checked':'')+'><img src="'+esc(safeImage(season.image||s.base.image))+'" alt="" loading="lazy"><span><strong>'+esc(M.label(season.number))+'</strong><small>'+esc(season.airDate||say('开播日期未知','Air date unknown'))+' · '+season.episodes+' '+say('集','episodes')+(duplicate?' · '+say('已在资料库','In library'):'')+'</small></span></label>'+(migration&&!duplicate?fields(r):'')+'</article>'}).join('');
  $('#seasonPreviewTotal').textContent=migration?say('原记录：进度 '+s.source.progress+' / '+s.source.episodes+'，重看 '+(s.source.rewatchCount||0)+' 次，总观看 '+((s.source.rewatchCount||0)*s.source.episodes+s.source.progress)+' 集。','Original: '+s.source.progress+' / '+s.source.episodes+' episodes; '+(s.source.rewatchCount||0)+' rewatches; '+((s.source.rewatchCount||0)*s.source.episodes+s.source.progress)+' total episodes watched.'):'';$('#seasonConfirmRow').hidden=!migration;$('#seasonConfirm').checked=false;$('#seasonAllowReduction').checked=false;$('#seasonCommit').textContent=migration?say('确认拆分并迁移','Confirm split and migrate'):say('添加所选季度','Add selected seasons');$('#seasonCommit').disabled=false;$('#seasonStatusMessage').textContent='';
 }
 async function open(base,source=null){const token=++generation;session={base:structuredClone(base),source:source?structuredClone(source):null,seasons:[],revisions:Object.fromEntries(['anishelf-library-v1','anishelf-watch-history-v1','anishelf-lists-v1'].map(k=>[k,AppStorage.getItem(k)]))};$('#seasonDialog').showModal();$('#seasonRows').innerHTML='';$('#seasonDialogTitle').textContent=base.title;$('#seasonStatusMessage').textContent=say('正在准备季度列表…','Preparing seasons…');$('#seasonCommit').disabled=true;
  try{if(base.tmdbId&&tmdbCredential){const data=await TMDB.request('tv/'+base.tmdbId,tmdbCredential,{append_to_response:'images,aggregate_credits',include_image_language:'zh,ja,en,null'});if(token!==generation)return;session.base={...TMDB.normalize(data,'tv'),id:base.id,seriesKey:base.seriesKey};}
   if(token!==generation)return;session.seasons=(session.base.allSeasons||session.base.seasons||[]).filter(s=>Number.isInteger(s.number)&&s.number>=0).sort((a,b)=>a.number-b.number);
   if(!session.seasons.length){$('#seasonManual').hidden=false;$('#seasonManualCounts').value='';$('#seasonStatusMessage').textContent=say('没有季度资料。可以填写每季集数，例如 12,13；这不会访问网络。','No season data. Enter episode counts, e.g. 12,13, to define seasons offline.');return}
   $('#seasonManual').hidden=true;draw();
  }catch(error){if(token===generation){$('#seasonStatusMessage').textContent=error.message;$('#seasonManual').hidden=false;$('#seasonManualCounts').value='';}}
 }
 async function openSeries(id){if(library.some(a=>a.tmdbType==='tv'&&a.tmdbId===id&&legacy(a))){const source=library.find(a=>a.tmdbType==='tv'&&a.tmdbId===id&&legacy(a));return open(source,source)}return open({tmdbId:id,tmdbType:'tv',title:say('选择季度','Select seasons'),image:'',episodes:1})}
 function choices(){return $$('#seasonRows [data-season-choice]:checked:not(:disabled)').map(el=>Number(el.dataset.seasonChoice))}
 const personal=['favorite','tag','shuffleExcluded','watchSite'];
 async function commit(){if(busy||!session)return;const selected=choices(),s=session,token=generation;if(!selected.length){$('#seasonStatusMessage').textContent=say('至少选择一个季度。','Select at least one season.');return}if(s.source&&!$('#seasonConfirm').checked){$('#seasonStatusMessage').textContent=say('请先勾选迁移确认。','Confirm the migration preview first.');return}
  busy=true;$('#seasonRows').inert=true;$('#seasonConfirmRow').inert=true;$('#seasonCommit').disabled=true;$('#seasonStatusMessage').textContent=say('正在加载并保存季度…','Loading and saving seasons…');
  try{const entries=[];for(const number of selected){if(token!==generation)return;const season=s.seasons.find(v=>v.number===number);let data=null;if(s.base.tmdbId&&tmdbCredential&&!s.manual)data=await TMDB.request('tv/'+s.base.tmdbId+'/season/'+number,tmdbCredential,{append_to_response:'aggregate_credits'});if(token!==generation)return;const a=M.from(s.base,season,data);
    if(s.source){for(const k of personal)if(s.source[k]!==undefined)a[k]=s.source[k];Object.assign(a,{progress:Number($('#seasonProgress'+number).value),status:$('#seasonStatus'+number).value,rewatchCount:Number($('#seasonRewatch'+number).value),startDate:$('#seasonStart'+number).value,finishDate:$('#seasonFinish'+number).value});if(!datesValid(a.startDate)||!datesValid(a.finishDate))throw Error(say('观看日期无效。','Invalid watch date.'));if(['watching','rewatching'].includes(a.status)){a.status=a.rewatchCount?'rewatching':'watching';a.watchDays=WatchSchedule.recordDays(s.source)}}entries.push(a)}
   if(token!==generation)return;for(const [k,value]of Object.entries(s.revisions))if(AppStorage.getItem(k)!==value)throw Error(say('资料已在其他操作或窗口中变化，请重新打开季度预览。','Data changed in another operation or window. Reopen the season preview.'));
   if(s.source){const current=library.find(a=>a.id===s.source.id);if(JSON.stringify(current)!==JSON.stringify(s.source))throw Error(say('原记录已变化，请重新打开迁移预览。','The original record changed. Reopen the migration preview.'));const source={...s.source,seasons:s.seasons},plan=M.plan(source,entries,library,WatchHistory.exportRecords(),AniLists.exportLists(),archive(),$('#seasonAllowReduction').checked);
    WatchHistory.validate(plan.history);AniLists.validate(plan.lists);M.transaction({'anishelf-library-v1':JSON.stringify(plan.library),'anishelf-watch-history-v1':JSON.stringify(plan.history),'anishelf-lists-v1':JSON.stringify(plan.lists),[key]:JSON.stringify(plan.archive)});library=plan.library;WatchHistory.replaceRecords(plan.history,library);AniLists.replaceLists(plan.lists);
   }else{if(entries.some(a=>owned(a,a.seasonNumber)))throw Error(say('季度已被添加，请重新选择。','A selected season was already added. Select again.'));const next=[...entries,...library];AppStorage.setItem('anishelf-library-v1',JSON.stringify(next));library=next;}
   $('#seasonDialog').close();render();renderTmdbResults();toast(say('季度已保存','Seasons saved'));
  }catch(error){$('#seasonStatusMessage').textContent=error.recoveryPending?say('保存未完成，恢复日志已保留。请重新打开此页面恢复原数据，再继续操作。','Saving did not finish. Recovery data was retained. Reopen this page to restore the original data before continuing.'):error.name==='QuotaExceededError'?say('浏览器存储空间不足，拆分未完成，原数据未被替换。请先导出备份；可恢复默认背景以释放空间，再重试。','Browser storage is full. The split was not completed and the original data was not replaced. Export a backup first; restoring the default background may free space for a retry.'):error.message}finally{busy=false;$('#seasonRows').inert=false;$('#seasonConfirmRow').inert=false;$('#seasonCommit').disabled=false}
 }
 $('#seasonCommit').onclick=commit;
 $('#seasonDialog').addEventListener('close',()=>{generation++;session=null});
 $('#seasonManualApply').onclick=()=>{if(!session)return;const counts=$('#seasonManualCounts').value.split(',').map(v=>Number(v.trim()));if(!counts.length||counts.length>100||counts.some(n=>!Number.isInteger(n)||n<1||n>9999)){ $('#seasonStatusMessage').textContent=say('请使用逗号分隔的有效集数。','Enter valid comma-separated episode counts.');return}session.manual=true;session.seasons=counts.map((episodes,i)=>({number:i+1,episodes,name:M.label(i+1),airDate:''}));session.base.seasons=session.seasons;draw()};
 function noteRepairs(){let next=library;for(const record of archive()){if(!record.source.note)continue;for(const a of M.leaves(next))if(M.isSeason(a)&&a.seasonNumber===1&&M.seriesKey(a)===M.seriesKey(record.source))next=M.patch(next,a.id,{note:M.mergeNotes(a.note,record.source.note)})}return next}
 function repairNotes(){const next=noteRepairs();const changed=M.leaves(next).filter(a=>a.note!==M.find(library,a.id)?.note).length;if(!changed)return 0;AppStorage.setItem('anishelf-library-v1',JSON.stringify(next));library=next;render();return changed}
 function settings(){const old=library.filter(legacy),section=document.createElement('section');section.className='season-settings';section.innerHTML='<h3>'+say('季度管理','Season management')+'</h3><p>'+say('旧剧集保留原样，确认预览后再拆分；电影无需迁移。手动添加的旧条目可自行指定每季集数。','Legacy series stay unchanged until you confirm a split. Movies need no migration. Define season counts manually for old offline entries.')+'</p>'+(old.length?old.map((a,i)=>'<div class="season-legacy-row"><strong>'+esc(a.title)+'</strong><button data-migrate-season="'+i+'">'+say('拆分为季度','Split into seasons')+'</button></div>').join(''):'<p>'+say('没有待拆分的旧剧集。','No legacy series to split.')+'</p>')+'<p>'+say('原备注只迁移到第一季；已拆分的条目也可从档案补齐，已有不同备注会拼接保留。','Original notes go to Season 1 only. Restore notes from the archive for already split entries; different existing notes are preserved and combined.')+'</p><button id="repairSeasonNotes">'+say('补齐已拆分条目的第一季备注','Restore notes to Season 1')+'</button><button id="exportSeriesArchive">'+say('导出原始系列档案','Export original series archive')+'</button>';$('#extraSection .settings-panel').append(section);section.querySelectorAll('[data-migrate-season]').forEach(b=>b.onclick=()=>open(old[Number(b.dataset.migrateSeason)],old[Number(b.dataset.migrateSeason)]));section.querySelector('#repairSeasonNotes').onclick=()=>{try{const count=repairNotes();toast(count?say('已补齐 '+count+' 个第一季的备注','Restored notes for '+count+' Season 1 entries'):say('没有需要补齐的第一季备注。','No Season 1 notes need restoring.'))}catch(error){toast(error.name==='QuotaExceededError'?say('空间不足，备注未更改。请先导出备份。','Storage is full; notes were not changed. Export a backup first.'):error.message)}};section.querySelector('#exportSeriesArchive').onclick=()=>{try{const url=URL.createObjectURL(new Blob([JSON.stringify({seriesArchive:archive()},null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='anishelf-series-archive.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}catch(error){toast(error.message)}}}
 const offlineForm=$('#addForm');offlineForm.onsubmit=function(event){event.preventDefault();const f=new FormData(event.target),kind=f.get('entryType')||'season',number=Number(f.get('seasonNumber')??1),count=Number(f.get('episodes')),title=String(f.get('title')||'').trim(),year=Number(f.get('year')),status=f.get('status');
  if(!['season','movie'].includes(kind)||!title||title.length>100||!Number.isInteger(count)||count<1||count>9999||!Number.isInteger(year)||year<1900||year>2100||!Object.hasOwn(statuses,status)||kind==='season'&&(!Number.isInteger(number)||number<0||number>999)||kind==='movie'&&count!==1){toast(say('请检查名称、类型、季度编号和集数；电影集数为 1。','Check the title, type, season number and episode count. Movies have 1 episode.'));return}
  let id=Date.now();while(library.some(a=>a.id===id))id++;const a={id,title,en:'',year,episodes:count,progress:status==='completed'?count:0,status,rewatchCount:status==='rewatching'?1:0,rating:0,image:String(f.get('image')||''),genre:t('未分类'),tag:'',favorite:false,entryType:kind,...(kind==='movie'?{tmdbType:'movie'}:{seriesTitle:title,seriesKey:'local-'+id,seasonNumber:number,seasons:[{number,episodes:count,name:M.label(number),airDate:''}],title:(title.slice(0,97-M.label(number).length)+' · '+M.label(number))})};
  try{const next=[a,...library];AppStorage.setItem('anishelf-library-v1',JSON.stringify(next));library=next;page='library';filter='all';tag='';$('#search').value='';render();$('#addDialog').close();event.target.reset();$('#addForm [name="seasonNumber"]').disabled=false;toast(t('动漫已添加'))}catch(error){toast(error.message)}
 };
 const offlineKind=$('#addForm [name="entryType"]');offlineKind.onchange=()=>{const movie=offlineKind.value==='movie';$('#addForm [name="seasonNumber"]').disabled=movie;const count=$('#addForm [name="episodes"]');if(movie)count.value=1;else if(Number(count.value)===1)count.value=12};
 const baseSettings=renderSettings;renderSettings=function(){baseSettings();settings()};
 const baseDetail=renderDetail;renderDetail=function(a){baseDetail(a);const section=document.createElement('section');section.className='detail-section season-relations';const siblings=M.isSeason(a)?library.filter(b=>b.id!==a.id&&M.isSeason(b)&&M.seriesKey(b)===M.seriesKey(a)):[];
  section.innerHTML=M.isSeason(a)?'<h3>'+esc(a.seriesTitle)+'</h3><p>'+say('其他季度','Other seasons')+'</p>'+siblings.map((b,i)=>'<button data-sibling-season="'+i+'">'+esc(M.label(b.seasonNumber))+'</button>').join('')+(a.tmdbId?'<button id="addRelatedSeason">'+say('添加其他季度','Add other seasons')+'</button>':''):legacy(a)?'<button id="migrateDetailSeason">'+say('拆分为独立季度','Split into independent seasons')+'</button>':'';
  if(M.isSeason(a)){let original;try{original=archive().find(r=>r.seasonIds.includes(a.id))}catch{};if(original)section.innerHTML+='<details><summary>'+say('保留的原始系列记录','Preserved original series record')+'</summary><p>'+esc(JSON.stringify({rating:original.source.rating,note:original.source.note,startDate:original.source.startDate,finishDate:original.source.finishDate,rewatchCount:original.source.rewatchCount},null,2))+'</p></details>'}
  $('#detailBody .detail-content').append(section);section.querySelectorAll('[data-sibling-season]').forEach(b=>b.onclick=()=>openDetail(siblings[Number(b.dataset.siblingSeason)].id));if(legacy(a))section.querySelector('#migrateDetailSeason').onclick=()=>{closeDetailPanel();open(a,a)};if(M.isSeason(a)&&a.tmdbId)section.querySelector('#addRelatedSeason').onclick=()=>openSeries(a.tmdbId);
 };
 const baseLoad=loadDetailMetadata;loadDetailMetadata=async function(a,force=false){if(M.isMerged(a)){if(force)toast(say('请从下方季度记录中更新各季资料。','Update metadata from the season records below.'));return}if(!M.isSeason(a))return baseLoad(a,force);if(!a.tmdbId||(!force&&a.detailsVersion>=3&&a.metadataLanguage===I18n.getLanguage()))return;if(!tmdbCredential){$('#detailLoadStatus').textContent=say('请在设置中配置 TMDb 后刷新。','Configure TMDb in Settings to refresh.');return}try{const series=await TMDB.request('tv/'+a.tmdbId,tmdbCredential,{append_to_response:'images,aggregate_credits',include_image_language:'zh,ja,en,null'}),details=await TMDB.request('tv/'+a.tmdbId+'/season/'+a.seasonNumber,tmdbCredential,{append_to_response:'aggregate_credits'}),base=TMDB.normalize(series,'tv'),s=base.seasons.find(s=>s.number===a.seasonNumber);if(!s)throw Error('Season unavailable');const fresh=M.from(base,s,details),current=findLibraryEntry(a.id);if(!current)return;const next={...current,...fresh,id:current.id,episodes:Math.max(fresh.episodes,current.progress)};for(const k of [...personal,'progress','status','rating','note','rewatchCount','startDate','finishDate','watchDays','watchDay'])if(current[k]!==undefined)next[k]=current[k];const updated=patchLibraryEntry(a.id,next);AppStorage.setItem('anishelf-library-v1',JSON.stringify(updated));library=updated;Object.assign(a,next);if(selectedId===a.id&&$('#detailDialog').open)renderDetail(findLibraryEntry(a.id))}catch(error){if(selectedId===a.id)$('#detailLoadStatus').textContent=error.message}};
 return {open,openSeries,commit,archive,withArchive,repairNotes};
})();
